setBillingAddress.usageScenarios:
To set the billing address as the same as the shipping address:

```ts
import { setBillingAddress } from '@dropins/storefront-checkout/api.js';

await setBillingAddress({
  sameAsShipping: true,
});
```

To set a specific billing address:

```ts
import { setBillingAddress } from '@dropins/storefront-checkout/api.js';

await setBillingAddress({
  address: {
    firstName: 'John',
    lastName: 'Doe',
    street: ['123 Main St', 'Apt 1'],
    city: 'New York',
    postcode: '10001',
    countryCode: 'US',
    telephone: '555-555-5555',
  },
  sameAsShipping: false,
});
```

